void arrive_afterRetag_stillProcessesFrozenManifestByBagId() throws Exception {
    registerLeg("LEG1", "PEK", "SHA");
    registerLeg("LEG2", "SHA", "CAN");
    registerBag("ID-1", "B1", List.of("LEG1", "LEG2"));

    // LEG1 用 B1 封舱后到达 SHA
    load("LEG1", 1, Map.of("B1", 1));
    seal("LEG1", 2);
    arrive("LEG1", List.of("B1"));

    // LEG2 用 B2 封舱；封舱后、到达前换成 B3
    retag("ID-1", 1, "B2");
