    mockMvc.perform(get("/api/bags/B2/trace"))
            .andExpect(jsonPath("$.bagTag").value("B3"))
            .andExpect(jsonPath("$.status").value("DELIVERED"))
            .andExpect(jsonPath("$.nextLegIndex").value(2));
}

